/* The site's offline cache. GENERATED by build/sw_build.mjs -- do not edit.
 *
 * The cache name is a hash of everything listed below, so publishing any change
 * to any of these files produces a new cache, and the old one is deleted on
 * activation. That is the whole update story: there is no manual versioning to
 * forget, and no way to serve a stale page from a previous deploy.
 */
const CACHE = 'ladder-b6a4dadcb3f7';

const PRECACHE = [
  '.',
  '404.html',
  'fonts/bricolage-grotesque-500-latin.woff2',
  'fonts/bricolage-grotesque-700-latin.woff2',
  'fonts/bricolage-grotesque-800-latin.woff2',
  'fonts/fonts.css',
  'fonts/ibm-plex-mono-400-latin.woff2',
  'fonts/ibm-plex-mono-500-latin.woff2',
  'fonts/ibm-plex-mono-600-latin.woff2',
  'fonts/ibm-plex-sans-400-greek.woff2',
  'fonts/ibm-plex-sans-400-latin.woff2',
  'fonts/ibm-plex-sans-500-greek.woff2',
  'fonts/ibm-plex-sans-500-latin.woff2',
  'fonts/ibm-plex-sans-600-greek.woff2',
  'fonts/ibm-plex-sans-600-latin.woff2',
  'index.html',
  'software-engineering/ai-engineering.html',
  'software-engineering/algorithms.html',
  'software-engineering/aws.html',
  'software-engineering/cloud.html',
  'software-engineering/foundations.html',
  'software-engineering/go.html',
  'software-engineering/index.html',
  'software-engineering/java.html',
  'software-engineering/python.html',
];

self.addEventListener('install', event => {
  // Take over as soon as this finishes rather than waiting for every tab of the
  // old version to close; the pages are static documents, so there is no
  // half-updated state to land in.
  self.skipWaiting();
  event.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith('ladder-') && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;   // leave anything external alone

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);

    // A request for a directory is a request for its index.
    const hit = await cache.match(req, { ignoreSearch: true })
      || (url.pathname.endsWith('/')
        ? await cache.match(url.pathname + 'index.html', { ignoreSearch: true })
        : undefined);
    if (hit) return hit;

    try {
      return await fetch(req);
    } catch (err) {
      // Offline, and not something we hold. A navigation gets the site's own
      // 404 page rather than the browser's error screen; anything else fails
      // as it would have anyway.
      if (req.mode === 'navigate') {
        const fallback = await cache.match(new URL('404.html', self.registration.scope).pathname);
        if (fallback) return fallback;
      }
      throw err;
    }
  })());
});
